/**
 * Hand-built contract fixtures. `meta.envelope.json` is written by hand to the contract in
 * the task brief (not generated by the app or by the Python exporter), so a parser bug cannot
 * hide behind a fixture produced by the same code.
 */
import metaEnvelope from './meta.envelope.json'

export type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
export type Path = (string | number)[]

export const VALID_COMMIT = metaEnvelope.source_commit

/** A fresh deep copy each call, so a test can edit it freely. */
export function validMetaEnvelope(): Json {
  return structuredClone(metaEnvelope) as Json
}

function parentOf(root: Json, path: Path): Record<string | number, Json> {
  let node = root as Record<string | number, Json>
  for (const key of path.slice(0, -1)) node = node[key] as Record<string | number, Json>
  return node
}

/** The valid envelope with the value at `path` replaced. */
export function withValue(path: Path, value: Json): Json {
  const env = validMetaEnvelope()
  parentOf(env, path)[path[path.length - 1]] = value
  return env
}

/** The valid envelope with the key at `path` removed. */
export function without(path: Path): Json {
  const env = validMetaEnvelope()
  delete parentOf(env, path)[path[path.length - 1]]
  return env
}
